
import pandas as pd
import matplotlib.pyplot as plt
from pathlib import Path

results_folder = Path("results")

print("=" * 60)
print("PRODUCT REVIEW ANALYSIS FOR E-COMMERCE")
print("STEP 14: THREE-CLASS MODEL COMPARISON")
print("=" * 60)

# Metric files generated by the three models
metric_files = [
    results_folder / "logistic_regression_metrics.csv",
    results_folder / "naive_bayes_metrics.csv",
    results_folder / "svm_metrics.csv"
]

# Check that all files exist
for file in metric_files:
    if not file.exists():
        raise FileNotFoundError(
            f"Metric file not found: {file}. "
            "Make sure all three models have been trained."
        )

# Load the model metrics
dataframes = [pd.read_csv(file) for file in metric_files]
comparison = pd.concat(dataframes, ignore_index=True)

# Check required columns
required_columns = [
    "Model",
    "Accuracy",
    "Precision",
    "Recall",
    "F1_Score"
]

for column in required_columns:
    if column not in comparison.columns:
        raise ValueError(
            f"Required column '{column}' is missing from the metric files."
        )

# Convert metrics to percentages for easier interpretation
metric_columns = [
    "Accuracy",
    "Precision",
    "Recall",
    "F1_Score"
]

comparison_percent = comparison.copy()

for column in metric_columns:
    comparison_percent[column] = (
        comparison_percent[column] * 100
    ).round(2)

# Display the comparison table
print("\nTHREE-CLASS MODEL PERFORMANCE COMPARISON")
print("-" * 60)
print("Sentiment classes: Negative, Neutral, Positive")
print("Precision, Recall and F1-score use macro averaging.")
print()

print(
    comparison_percent[
        ["Model", "Accuracy", "Precision", "Recall", "F1_Score"]
    ].to_string(index=False)
)

# Save the comparison table
csv_path = results_folder / "model_comparison.csv"
comparison_percent.to_csv(csv_path, index=False)

# Create a comparison chart
ax = comparison_percent.plot(
    x="Model",
    y=["Accuracy", "F1_Score"],
    kind="bar",
    figsize=(10, 6),
    rot=0
)

ax.set_title("Three-Class Sentiment Model Comparison")
ax.set_xlabel("Machine Learning Model")
ax.set_ylabel("Score (%)")
ax.set_ylim(0, 100)
ax.legend(["Accuracy", "Macro F1-score"])
ax.grid(axis="y", linestyle="--", alpha=0.4)

plt.tight_layout()

chart_path = results_folder / "model_comparison.png"
plt.savefig(chart_path, dpi=300, bbox_inches="tight")
plt.show()

# Identify the highest accuracy
best_row = comparison.loc[comparison["Accuracy"].idxmax()]

print("\nBEST MODEL BY ACCURACY")
print("Model:", best_row["Model"])
print(f"Accuracy: {best_row['Accuracy'] * 100:.2f}%")

# Identify the highest macro F1-score
best_f1_row = comparison.loc[comparison["F1_Score"].idxmax()]

print("\nBEST MODEL BY MACRO F1-SCORE")
print("Model:", best_f1_row["Model"])
print(f"Macro F1-score: {best_f1_row['F1_Score'] * 100:.2f}%")

# Display saved file locations
print("\nSaved files:")
print("Comparison table:", csv_path.resolve())
print("Comparison chart:", chart_path.resolve())

print("\nStep 14 completed successfully.")
